using System;using System.Collections;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Security.Cryptography;using System.Text;using System.Threading;using System.Web.Script.Serialization;
using RichAudio.Beacon.Windows;using RichAudio.Beacon.Transport;
namespace RichAudio.Experiments {
 // Separate executable entry point. HostProgram has no experiment command.
 public static partial class Latency03Experiment {
  static readonly JavaScriptSerializer Json=new JavaScriptSerializer{MaxJsonLength=64000000,RecursionLimit=64};
  const string OriginalBedSha="e86d54d9f305b24dd86264d456f3f8786e741c0aaaaeab42a82bd70016a021fe";
  static void Need(bool b,string s){if(!b)throw new InvalidDataException(s);}
  public static string Digest(string file){using(var h=SHA256.Create())using(var s=File.OpenRead(file))return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
  static string DigestBytes(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static Dictionary<string,object> Read(string file){Need(new FileInfo(file).Length<=4000000,"Bounded JSON required");return Json.Deserialize<Dictionary<string,object>>(File.ReadAllText(file));}
  static int Number(Dictionary<string,object> d,string key){return Convert.ToInt32(d[key]);}
  static string Text(Dictionary<string,object> d,string key){return Convert.ToString(d[key]);}
  static string SafePath(string root,string relative){
   Need(!String.IsNullOrEmpty(relative)&&!Path.IsPathRooted(relative)&&relative.IndexOf(':')<0&&!relative.Contains("\\")&&!relative.Contains("//"),"Relative manifest path required");
   foreach(string p in relative.Split('/'))Need(p!="."&&p!=".."&&p.Length>0,"No path traversal");string full=Path.GetFullPath(Path.Combine(root,relative));Need(full.StartsWith(root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase),"Candidate path escape");
   for(string at=full;at!=null;at=Path.GetDirectoryName(at))if(File.Exists(at)||Directory.Exists(at))Need((File.GetAttributes(at)&FileAttributes.ReparsePoint)==0,"Linked candidate paths refused");return full;
  }
  sealed class Candidate {
   internal string Root,Manifest,Endpoint,Session,Node,Worker,Preparation,Bed;internal int Seconds;internal Dictionary<string,object> Data;
   internal Candidate(string root){Root=Path.GetFullPath(root).TrimEnd(Path.DirectorySeparatorChar);Manifest=SafePath(Root,"candidate.json");Data=Read(Manifest);Need(Number(Data,"schema")==1&&Text(Data,"kind")=="latency-03-original-synthetic-endpoint-proposal"&&Number(Data,"requestedPeriodFrames")==0&&Convert.ToDouble(Data["outputGain"])==1,"Exact baseline-period synthetic proposal required");Need(Text(Data,"burstPolicy")=="ProtectActiveTails03"&&!(bool)Data["recordingAllowed"]&&!(bool)Data["gameLaunchAllowed"]&&!(bool)Data["nativeAcquisitionAllowed"]&&!(bool)Data["nativeSuppressionAllowed"]&&!(bool)Data["normalPreferencesChanged"],"Fixed isolated experiment scope required");
    var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);var bindings=(IList)Data["bindings"];Need(bindings.Count>=10&&bindings.Count<=256,"Bounded explicit candidate bindings");foreach(Dictionary<string,object> b in bindings){string name=Text(b,"file");Need(seen.Add(name),"Duplicate binding");string p=SafePath(Root,name);Need(File.Exists(p)&&new FileInfo(p).Length==Convert.ToInt64(b["bytes"])&&Digest(p)==Text(b,"sha256"),"Candidate binding mismatch: "+name);}
    Node=Bound("nodeFile",seen);Worker=Bound("workerFile",seen);Preparation=Bound("preparationFile",seen);Bed=Bound("bedFile",seen);Need(Digest(Bed)==OriginalBedSha,"Only exact retained Bati reference PCM approved for this candidate");
    Need(seen.Contains("runtime/Latency03.Experiment.exe"),"Bound experiment executable required");Endpoint=Text(Data,"endpointId");Need(!String.IsNullOrWhiteSpace(Endpoint)&&Endpoint.Length<=1024,"One exact historical endpoint identity required");Session=Text(Data,"session");Need(System.Text.RegularExpressions.Regex.IsMatch(Session,"^[a-f0-9]{32}$"),"Bound authored session");Seconds=Number(Data,"maximumOutputSeconds");Need(Seconds==28,"Exact28second experiment protocol required");
   }
   string Bound(string key,HashSet<string> bindings){string p=Text(Data,key);Need(bindings.Contains(p),"Unbound execution/input path");return SafePath(Root,p);}
  }
  static float[] LoadBed(string file){byte[] b=File.ReadAllBytes(file);Need(b.Length<100000000&&Encoding.ASCII.GetString(b,0,4)=="RIFF"&&Encoding.ASCII.GetString(b,8,4)=="WAVE","Retained RIFF input required");bool format=false;int data=-1,n=0;for(int at=12;at+8<=b.Length;){int size=BitConverter.ToInt32(b,at+4);Need(size>=0&&at+8L+size<=b.Length,"RIFF chunk bounds");string kind=Encoding.ASCII.GetString(b,at,4);if(kind=="fmt "){int tag=BitConverter.ToUInt16(b,at+8);format=tag==3&&size>=16&&BitConverter.ToUInt16(b,at+10)==2&&BitConverter.ToInt32(b,at+12)==48000&&BitConverter.ToUInt16(b,at+22)==32;}if(kind=="data"){data=at+8;n=size;break;}at+=8+size+(size&1);}Need(format&&data>=0&&n%8==0,"Float32 stereo48k required");var pcm=new float[n/4];Buffer.BlockCopy(b,data,pcm,0,n);Need(pcm.Length/2>=30*48000,"No bed looping or replenishment from disk during output");foreach(float x in pcm)Need(!Single.IsNaN(x)&&!Single.IsInfinity(x)&&Math.Abs(x)<=.95,"Unscaled Bati PCM within declared original headroom");return pcm;}
  static byte[] SessionBytes(string session){var bytes=new byte[16];for(int i=0;i<16;i++)bytes[i]=Convert.ToByte(session.Substring(i*2,2),16);return bytes;}
  static PreparedTransientBus LoadBank(Candidate c){var prep=Read(c.Preparation);Need(Text(prep,"experimentProfile")=="LATENCY-03"&&(bool)prep["passed"]&&!(bool)prep["endpointOpened"]&&!(bool)prep["nativeEventAcquired"],"Original synthetic prewarm required");var p=(Dictionary<string,object>)prep["payload"];Need(Text(p,"file")=="kernels.f32le","Bound bank filename");string rawPath=Path.Combine(Path.GetDirectoryName(c.Preparation),"kernels.f32le");byte[] payload=File.ReadAllBytes(rawPath);Need(payload.Length==1048576&&DigestBytes(payload)==Text(p,"sha256"),"Bound eight-kernel payload");byte[] id=SessionBytes(c.Session);var bus=new PreparedTransientBus(BitConverter.ToUInt64(id,0),BitConverter.ToUInt64(id,8),.95,TransientBurstPolicy.ProtectActiveTails03);var kernels=(IList)prep["kernels"];Need(kernels.Count==8,"Eight source-specific kernels required");for(int s=0;s<8;s++){var k=(Dictionary<string,object>)kernels[s];int frames=Number(k,"frames"),offset=Number(k,"offsetBytes"),bytes=Number(k,"bytes");Need(Number(k,"kernelSlot")==s&&Number(k,"sourceId")==s+1&&frames==16384&&bytes==frames*8&&offset==s*bytes,"Exact slot layout");var pcm=new float[frames*2];Buffer.BlockCopy(payload,offset,pcm,0,bytes);var chunk=new byte[bytes];Buffer.BlockCopy(payload,offset,chunk,0,bytes);Need(DigestBytes(chunk)==Text(k,"pcmSha256"),"Kernel digest");bus.Register(s,new PreparedTransientKernel(pcm,frames,Number(k,"firstNonzeroFrame"),Number(k,"lastNonzeroFrame"),s+1,Number((Dictionary<string,object>)k["sourcePose"],"generation"),Number(k,"sceneGeneration"),Number((Dictionary<string,object>)k["listenerPose"],"generation"),1,Convert.ToDouble(k["physicalDirectDelayFrames"])));}return bus;}
  static object Validate(Candidate c){var bed=LoadBed(c.Bed);var bus=LoadBank(c);Need(!bus.ClockReady,"Validation must not invent/initialize a device clock");return new{passed=true,kind="offline-candidate-validation-only",manifestSha256=Digest(c.Manifest),bedFrames=bed.Length/2,preparedKernels=8,plannedEvents=Plan().Length,highResolutionQpcAvailable=Stopwatch.IsHighResolution,callbackAllocationCounterAvailable=Latency03OutputSession.AllocatedBytes()>=0,endpointOpened=false,endpointPeriodQueried=false,deviceCapability="Unqueried until fresh explicitly approved experiment",gameLaunched=false,recordingStarted=false};}
  static Dictionary<string,object> InputEvent(int id,int slot,long before,long after,long frequency){return new Dictionary<string,object>{{"eventId",id},{"sourceId",slot+1},{"sourceGeneration",1},{"kernelSlot",slot},{"kernelGeneration",1},{"sceneGeneration",1},{"listenerGeneration",slot==4?2:1},{"sourceEventSequence",id-1},{"priority",slot<4?0:1},{"extraClockUncertaintyFrames",0},{"maximumSoftwareLatenessFrames",2400},{"timing",new{basis="authored-fixture-clock",occurrenceLowerQpc=before,occurrenceUpperQpc=after,acquisitionBeforeQpc=before,observationAfterQpc=after,qpcFrequency=frequency}}};}
  static void WriteNew(string path,object value){using(var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write,FileShare.Read))using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))writer.WriteLine(Json.Serialize(value));}
  public static int Main(string[] args){try{Need(args.Length>=2,"Explicit --validate or --supervise-approved mode required");var c=new Candidate(args[1]);if(args[0]=="--validate"&&args.Length==2){Console.WriteLine(Json.Serialize(Validate(c)));return 0;}if(args[0]=="--supervise-approved"&&args.Length==5)return Supervise(c,args[2],args[3],args[4]);if(args[0]=="--owned-experiment-worker"&&args.Length==4)return RunWorker(c,args[2],args[3]);throw new InvalidDataException("No automatic endpoint entry or default mode");}catch(Exception e){Console.Error.WriteLine(e);return 1;}}
 }
